import requests

# %% ../nbs/api/invenio.ipynb #4ee6b0cb
ZENODO_API = 'https://zenodo.org/api/records'

# %% ../nbs/api/invenio.ipynb #c240efcf
def fetch_file(
    record_id: int, # Record id
    key: str, # File name, as the record's `files` list gives it
    base_url: str=ZENODO_API # API base URL of the repository's records
) -> bytes: # File content
    "Download file `key` of record `record_id`"
    resp = requests.get(f'{base_url}/{record_id}/files/{key}/content', timeout=60)
    resp.raise_for_status()
    return resp.content
